import express from 'express';
import path from 'path';
import { fileURLToPath } from 'url';
import { createServer as createViteServer } from 'vite';
import { GoogleGenAI } from '@google/genai';
import dotenv from 'dotenv';

dotenv.config();

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

async function startServer() {
  const app = express();
  const PORT = 3000;

  app.use(express.json({ limit: '10mb' }));

  // Initialize Gemini AI lazily
  let aiClient: GoogleGenAI | null = null;
  function getAI() {
    if (!aiClient) {
      const apiKey = process.env.GEMINI_API_KEY;
      if (!apiKey || apiKey === 'MY_GEMINI_API_KEY') {
        throw new Error('GEMINI_API_KEY is not configured.');
      }
      aiClient = new GoogleGenAI({ apiKey });
    }
    return aiClient;
  }

  // API Routes
  app.get('/api/health', (req, res) => {
    res.json({ status: 'ok', timestamp: new Date().toISOString() });
  });

  // AI Tutor & Diagnostic Endpoint
  app.post('/api/ai/tutor', async (req, res) => {
    try {
      const { prompt, context } = req.body;
      const ai = getAI();
      const response = await ai.models.generateContent({
        model: 'gemini-2.5-flash',
        contents: `Você é um tutor especialista de altíssimo nível em exames do ITA (Instituto Tecnológico de Aeronáutica).
Sua missão é ajudar o estudante com explicações extremamente rigorosas porém didáticas, com foco nas pegadinhas, matemática e física avançadas, equações e métodos do ITA.

Contexto do aluno: ${context || 'Estudando para o vestibular ITA'}
Pergunta/Demanda: ${prompt}

Responda em Português do Brasil com formatação limpa em Markdown. Se houver fórmulas, use sintaxe em LaTeX (como $E = mc^2$ ou $$\\int_{0}^{\\infty} x dx$$).`
      });

      res.json({ success: true, text: response.text });
    } catch (err: any) {
      console.error('Error in Gemini API:', err?.message || err);
      res.status(500).json({
        success: false,
        error: err?.message || 'Erro ao comunicar com a IA do Gemini.'
      });
    }
  });

  // AI Flashcard Generator
  app.post('/api/ai/generate-cards', async (req, res) => {
    try {
      const { subject, topic, count = 3 } = req.body;
      const ai = getAI();
      const response = await ai.models.generateContent({
        model: 'gemini-2.5-flash',
        contents: `Gere ${count} flashcards de alto nível para o vestibular ITA sobre o assunto "${topic}" da matéria "${subject}".
Retorne ESTRITAMENTE um array JSON válido sem marcação de código fora do JSON ou retorne dentro de \`\`\`json ... \`\`\`.
Cada objeto deve conter:
- "front": Pergunta ou conceito desafiador do ITA (pode conter notação LaTeX com $ ou $$).
- "back": Resposta detalhada, passo a passo, fórmula chave e dica do ITA.
- "tags": Array de tags (ex: ["ITA", "${subject}", "Fórmula"]).`
      });

      const rawText = response.text || '';
      const jsonMatch = rawText.match(/\[[\s\S]*\]/);
      if (jsonMatch) {
        const cards = JSON.parse(jsonMatch[0]);
        res.json({ success: true, cards });
      } else {
        res.status(500).json({ success: false, error: 'Formato inválido retornado pela IA.' });
      }
    } catch (err: any) {
      res.status(500).json({ success: false, error: err?.message || 'Erro ao gerar flashcards.' });
    }
  });

  // Serve Vite in dev or static in prod
  if (process.env.NODE_ENV !== 'production') {
    const vite = await createViteServer({
      server: { middlewareMode: true },
      appType: 'spa',
    });
    app.use(vite.middlewares);
  } else {
    const distPath = path.join(process.cwd(), 'dist');
    app.use(express.static(distPath));
    app.get('*', (req, res) => {
      res.sendFile(path.join(distPath, 'index.html'));
    });
  }

  app.listen(PORT, '0.0.0.0', () => {
    console.log(`Server running on http://0.0.0.0:${PORT}`);
  });
}

startServer();
